"use strict";(globalThis.webpackChunkcardano_updates=globalThis.webpackChunkcardano_updates||[]).push([[46425],{53931(e,t,s){s.r(t),s.d(t,{assets:()=>l,contentTitle:()=>i,default:()=>h,frontMatter:()=>r,metadata:()=>o,toc:()=>c});var o=s(17987),n=s(74848),a=s(28453);const r={title:"Consensus Team Update",slug:"2026-09-22-consensus",authors:"dnadales",tags:["consensus"],hide_table_of_contents:!1},i=void 0,l={authorsImageUrls:[void 0]},c=[{value:"High level summary",id:"high-level-summary",level:2}];function d(e){const t={a:"a",code:"code",h2:"h2",li:"li",ul:"ul",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.h2,{id:"high-level-summary",children:"High level summary"}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:["Leios prototype development (Treasury Funding Initiative 4: Ouroboros Leios Implementation):\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:["Split the Leios database into two files, one for data a node can still roll back, and one for data that is settled. A certified Endorser Block moves from the first file to the second in the background. An operator can put the two files on different disks, and give the busier file the faster disk. The same change adds garbage collection in small steps: one thread marks the rows a node no longer needs, and a second thread deletes them in paced batches, so the deletion does not hold up the rest of the node (",(0,n.jsx)(t.a,{href:"https://github.com/IntersectMBO/ouroboros-consensus/pull/2261",children:"#2261"}),", for ",(0,n.jsx)(t.a,{href:"https://github.com/input-output-hk/ouroboros-leios/issues/969",children:"ouroboros-leios#969"}),")."]}),"\n",(0,n.jsxs)(t.li,{children:["Adapted the prototype node to the two file layout, and published the size of each part as a node metric (",(0,n.jsx)(t.a,{href:"https://github.com/IntersectMBO/cardano-node/pull/6656",children:"cardano-node#6656"}),"). Added a dashboard that shows how many Endorser Blocks and transactions sit in each part, and updated the devnet configuration to match (",(0,n.jsx)(t.a,{href:"https://github.com/input-output-hk/ouroboros-leios/pull/1054",children:"ouroboros-leios#1054"}),")."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.code,{children:"db-synthesizer"})," now builds a Leios chain instead of a chain of empty blocks. It fills each block with transactions, puts what does not fit into an Endorser Block, and votes on each announced Endorser Block so that a later block can certify it. It also stores each Endorser Block it forges, which an earlier version dropped. The other database tools now have a Leios chain to work on (",(0,n.jsx)(t.a,{href:"https://github.com/IntersectMBO/ouroboros-consensus/pull/2241",children:"#2241"}),", ",(0,n.jsx)(t.a,{href:"https://github.com/IntersectMBO/ouroboros-consensus/pull/2283",children:"#2283"}),")."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.code,{children:"db-truncater"})," now handles a Leios chain. After it cuts the chain back to a chosen slot, it cuts the Leios database back to the same slot, drops the transactions that no Endorser Block refers to, and shrinks the file (",(0,n.jsx)(t.a,{href:"https://github.com/IntersectMBO/ouroboros-consensus/pull/2262",children:"#2262"}),", for ",(0,n.jsx)(t.a,{href:"https://github.com/input-output-hk/ouroboros-leios/issues/1023",children:"ouroboros-leios#1023"}),")."]}),"\n",(0,n.jsxs)(t.li,{children:["Moved block forging out of the node kernel into a module of its own, and split it into named steps. The behaviour does not change. The new shape makes the forging path easier to follow, easier to instrument, and easier to reuse from the database tools (",(0,n.jsx)(t.a,{href:"https://github.com/IntersectMBO/ouroboros-consensus/pull/2281",children:"#2281"}),")."]}),"\n"]}),"\n"]}),"\n",(0,n.jsxs)(t.li,{children:["Maintenance and support (Treasury Funding Initiative 17: Maintenance and Support):\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:["Dropped support for node-to-client protocol versions below v23. Version 23 shipped with node 10.7.0 in March 2026, and every client we checked already offers it. The older versions kept legacy code alive in the consensus layer (",(0,n.jsx)(t.a,{href:"https://github.com/IntersectMBO/ouroboros-consensus/pull/2265",children:"#2265"}),")."]}),"\n"]}),"\n"]}),"\n"]})]})}function h(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},28453(e,t,s){s.d(t,{R:()=>r,x:()=>i});var o=s(96540);const n={},a=o.createContext(n);function r(e){const t=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),o.createElement(a.Provider,{value:t},e.children)}},17987(e){e.exports=JSON.parse('{"permalink":"/2026-09-22-consensus","editUrl":"https://github.com/intersectmbo/cardano-updates/tree/main/blog/2026-09-22-consensus.md","source":"@site/blog/2026-09-22-consensus.md","title":"Consensus Team Update","description":"High level summary","date":"2026-09-22T00:00:00.000Z","tags":[{"inline":true,"label":"consensus","permalink":"/tags/consensus"}],"readingTime":2.25,"hasTruncateMarker":false,"authors":[{"name":"Damian Nadales","title":"Consensus Team Lead","url":"https://github.com/dnadales","imageURL":"https://github.com/dnadales.png","key":"dnadales","page":null}],"frontMatter":{"title":"Consensus Team Update","slug":"2026-09-22-consensus","authors":"dnadales","tags":["consensus"],"hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Plutus Core Team Update","permalink":"/2026-09-23-plutus-core"},"nextItem":{"title":"Mithril Team Update","permalink":"/2026-09-16-mithril"}}')}}]);